        ["OnOtherCardEnterPlay"] = OnOtherCardEnterPlay,
        ["OnOtherCardLeaveBoardOrOwner"] = OnOtherCardLeaveBoardOrOwner,
        ["RemoveBuff"] = RemoveBuff,
    };
}
}
